  "anomalies": [
    {
      "category": "other",
      "components": ["FCC1", "NAVC1"],
      "pins": ["FCC1.48", "FCC1.73", "NAVC1.VCAP_1", "NAVC1.VCAP_2"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC", "I2C3_SDA_NAVC", "UART3_TX_NAVC"],
      "observed": "The FCC STM32H753 VCAP pins are connected to UART3_TX_FCC and UART3_RX_FCC; the NAVC STM32F405 VCAP pins are assigned to signal nets including I2C3_SDA_NAVC and UART3_TX_NAVC. No VCAP decoupling capacitors are shown.",
      "expected": "VCAP pins on these MCUs should be used for the required core-regulator capacitors, not as signal connections. UART and I2C signals should use valid GPIO/alternate-function pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC1 pins 48 VCAP and 73 VCAP carry UART3_TX_FCC and UART3_RX_FCC labels; sheet Flight Control Computer, page 2."
        },
        {
          "source": "schematic",
          "quote": "NAVC1 VCAP_1 and VCAP_2 are assigned signal labels including I2C3_SDA_NAVC and UART3_TX_NAVC; sheet Navigation Computer, page 3."
        },
        {
          "source": "schematic",
          "quote": "\"UART3 -> Debug (via USB)\"; sheet Navigation Computer, page 3."
        },
        {
          "source": "spec",
          "quote": "FCC: STM32H753VITx; NAVC: STM32F405RGTx."
        }
      ],
      "impact": "The required internal core supplies may be unstable or fail to operate, potentially preventing either MCU from starting reliably. Signals assigned to VCAP cannot function as UART or I2C GPIOs, so the affected debug and peripheral links will not work as intended.",
      "confidence": 0.99
    }
  ],
  "summary": "The schematic connects MCU VCAP pins to signal nets and omits their required decoupling capacitors. This affects both processors and is a functional hardware error, not the documented barometer pin-mix issue."
}

